        return {}
    else:
        return getproxies()

urllib3.filepost.iter_field_objects:
def iter_field_objects(fields):
    """
    Iterate over fields.

    Supports list of (k, v) tuples and dicts, and lists of
    :class:`~urllib3.fields.RequestField`.

    """
    if isinstance(fields, dict):
        i = six.iteritems(fields)
    else:
        i = iter(fields)
    for field in i:
        if isinstance(field, RequestField):
            yield field
        else:
            yield RequestField.from_tuples(*field)

urllib3.util.connection._set_socket_opti:
def _set_socket_options(sock, options):
    if options is None:
        return
    for opt in options:
        sock.setsockopt(*opt)

urllib3.util.connection.create_connectio:
def create_connection(address, timeout=socket._GLOBAL_DEFAULT_TIMEOUT, source_address=None, socket_options=None):
    """Connect to *address* and return the socket object.

    Convenience function.  Connect to *address* (a 2-tuple ``(host,
    port)``) and return the socket object.  Passing the optional
    *timeout* parameter will set the timeout on the socket instance
    before attempting to connect.  If no *timeout* is supplied, the
    global default timeout setting returned by :func:`socket.getdefaulttimeout`
    is used.  If *source_address* is set it must be a tuple of (host, port)
    for the socket to bind as a source address before making the connection.
    An host of '' or port 0 tells the OS to use the default.
    """
    (host, port) = address
    if host.startswith('['):
        host = host.strip('[]')
    err = None
    family = allowed_gai_family()
    try:
        host.encode('idna')
    except UnicodeError:
        return six.raise_from(LocationParseError("'%s', label empty or too long" % host), None)
    for res in socket.getaddrinfo(host, port, family, socket.SOCK_STREAM):
        (af, socktype, proto, canonname, sa) = res
        sock = None
        try:
            sock = socket.socket(af, socktype, proto)
            _set_socket_options(sock, socket_options)
            if timeout is not socket._GLOBAL_DEFAULT_TIMEOUT:
                sock.settimeout(timeout)
            if source_address:
                sock.bind(source_address)
            sock.connect(sa)
            return sock
        except socket.error as e:
            err = e
            if sock is not None:
                sock.close()
                sock = None
    if err is not None:
        raise err
    raise socket.error('getaddrinfo returns an empty list')

requests.utils.unquote_header_value:
def unquote_header_value(value, is_filename=False):
    """Unquotes a header value.  (Reversal of :func:`quote_header_value`).
    This does not use the real unquoting but what browsers are actually
    using for quoting.

    :param value: the header value to unquote.
    :rtype: str
    """
    if (value and value[0] == value[-1] == '"'):
        value = value[1:-1]
        if (not is_filename or value[:2] != '\\\\'):
            return value.replace('\\\\', '\\').replace('\\"', '"')
    return value
